        "everyday|2:1|4|text": "રવિ પુણેની એક કંપનીના મહત્ત્વના ફોનની રાહ જોતો હતો. તેનો ફોન વાગ્યો, પણ ફોન કરનારે સુરેશ નામના કોઈ માણસ વિશે પૂછ્યું. રવિએ નમ્રતાથી કહ્યું કે તેમણે ખોટો નંબર લગાડ્યો છે. થોડી મિનિટ પછી, જ્યારે તે લિફ્ટમાં હતો, ત્યારે તેને કંપનીનો મિસ્ડ કૉલ આવ્યો. તેણે તરત જ એ નંબર લગાડ્યો, પણ લાઇન વ્યસ્ત હતી. પછી તેની બેટરી પાંચ ટકા પર આવી ગઈ, અને ચાર્જર તો તે ઘરે જ ભૂલી આવ્યો હતો. એક ભલા દુકાનદારે તેને પોતાનું ચાર્જર વાપરવા દીધું, અને આખરે તેનો ફોન લાગ્યો. મેનેજર હસી પડ્યાં અને બોલ્યાં કે તેઓ પોતે જ તેને સામો ફોન કરવાનાં હતાં.",
