        "everyday|4:1|0|w0": "મેનુ",
        "everyday|4:1|0|w1": "વેઇટર",
        "everyday|4:1|0|w2": "સ્ટાર્ટર",
        "everyday|4:1|0|w3": "મુખ્ય વાનગી",
        "everyday|4:1|0|w4": "મીઠી વાનગી",
        "everyday|4:1|0|w5": "નેપકિન",
        "everyday|4:1|1|p0": "સાંભળો, પ્લીઝ અમને મેનુ અને થોડું પાણી આપશો?",
        "everyday|4:1|1|p1": "વેઇટરે નીર ઢોંસા ખાવાની સલાહ આપી, એટલે અમે બે પ્લેટ મંગાવી.",
        "everyday|4:1|1|p2": "આપણે એક સ્ટાર્ટર વહેંચીને ખાઈએ અને પછી પોતપોતાની મુખ્ય વાનગી મંગાવીએ?",
        "everyday|4:1|1|p3": "મારું પેટ ભરાઈ ગયું છે, મીઠી વાનગી નહીં ખવાય, પણ એક ફિલ્ટર કોફી ચોક્કસ પીશ.",
        "everyday|4:1|1|p4": "થોડા વધારે નેપકિન અને મારા દીકરા માટે એક નાની ચમચી લાવી આપશો?",
