        "services|3:1|0|w0": "પ્લમ્બર",
        "services|3:1|0|w1": "ઇલેક્ટ્રિશિયન",
        "services|3:1|0|w2": "લીકેજ",
        "services|3:1|0|w3": "નળ",
        "services|3:1|0|w4": "વાયરિંગ",
        "services|3:1|0|w5": "ફ્યુઝ",
        "services|3:1|1|p0": "રસોડાનો નળ આખી રાત ટપકતો રહ્યો; આજે કોઈ પ્લમ્બર મોકલી શકશો?",
        "services|3:1|1|p1": "બાથરૂમના સિંકની નીચે લીકેજ છે, અને ફરસ હંમેશાં ભીની રહે છે.",
        "services|3:1|1|p2": "હું જ્યારે પણ ગીઝર ચાલુ કરું છું, ત્યારે ફ્યુઝ ઊડી જાય છે.",
        "services|3:1|1|p3": "ઇલેક્ટ્રિશિયન કહે છે કે આ ફ્લેટનું જૂનું વાયરિંગ સલામત નથી.",
        "services|3:1|1|p4": "કોઈ પણ વાયરને અડતાં પહેલાં પ્લીઝ મેઇન સ્વિચ બંધ કરો.",
        "services|3:1|2|w0": "ઘરેલુ ઉપકરણ",
        "services|3:1|2|w1": "ખામી",
        "services|3:1|2|w2": "ટેક્નિશિયન",
        "services|3:1|2|w3": "સ્પેર પાર્ટ",
        "services|3:1|2|w4": "અંદાજ",
        "services|3:1|2|w5": "સર્વિસ ચાર્જ",
        "services|3:1|3|p0": "અમારા વૉશિંગ મશીનમાં ખામી છે; દર વખતે કપડાં ધોતાં ધોતાં વચ્ચે જ બંધ થઈ જાય છે.",
        "services|3:1|3|p1": "ટેક્નિશિયન કાલે સવારે, હું કામ પર નીકળું તે પહેલાં આવી શકે?",
        "services|3:1|3|p2": "કામ શરૂ કરતાં પહેલાં, કુલ ખર્ચનો અંદાજ આપી શકશો?",
        "services|3:1|3|p3": "સ્પેર પાર્ટને બેંગલુરુથી આવતાં ત્રણ દિવસ લાગશે.",
        "services|3:1|3|p4": "કોઈ પણ મોટા ઉપકરણ માટે સર્વિસ ચાર્જ દરેક મુલાકાતના ત્રણસો રૂપિયા છે.",
        "services|3:1|4|title": "ઠંડું ન કરતું ફ્રિજ",
        "services|3:1|4|text": "મે મહિનાના એક ગરમ અઠવાડિયામાં કલબુર્ગીમાં કુલકર્ણી પરિવારનું ફ્રિજ અચાનક ઠંડું કરતું બંધ થઈ ગયું. સુનીતાએ કંપનીના સર્વિસ સેન્ટરમાં ફોન કર્યો અને ખામી સ્પષ્ટ સમજાવી: લાઇટ ચાલુ હતી, પણ અંદર ગરમ હતું. બીજે દિવસે બપોરે એક ટેક્નિશિયન આવ્યો અને ઉપકરણ ધ્યાનથી તપાસ્યું. તેણે કહ્યું કે કૂલિંગ સિસ્ટમનો એક સ્પેર પાર્ટ ખરાબ થઈ ગયો છે અને તે બદલવો પડશે. કામ શરૂ કરતાં પહેલાં સુનીતાએ નમ્રતાથી અંદાજ માંગ્યો, અને તેણે કહ્યું કે સર્વિસ ચાર્જ સાથે કુલ ખર્ચ આશરે બે હજાર રૂપિયા થશે. બે દિવસ પછી પાર્ટ હુબ્બલીથી આવ્યો, અને ટેક્નિશિયને એક કલાકમાં ફ્રિજ રિપેર કરી દીધું. તે સાંજે ફ્રિજ ફરી ઠંડું થઈ ગયું, અને પરિવાર આખરે દૂધ અને દહીં સાચવી શક્યો.",
        "services|3:1|4|q0": "ફ્રિજમાં શું તકલીફ હતી?",
        "services|3:1|4|q0o0": "તે ઠંડું કરતું બંધ થઈ ગયું",
        "services|3:1|4|q0o1": "તેનો દરવાજો તૂટી ગયો હતો",
        "services|3:1|4|q0o2": "તે જોરથી અવાજ કરતું હતું",
        "services|3:1|4|q0o3": "તેની લાઇટ ચાલતી નહોતી",
        "services|3:1|4|q1": "કામ શરૂ થતાં પહેલાં સુનીતાએ શું માંગ્યું?",
        "services|3:1|4|q1o0": "ખર્ચનો અંદાજ",
