        "services|6:1|4|q2": "પડોશણ તેના માટે શું લાવી?",
        "services|6:1|4|q2o0": "બિસી બેળે ભાતની પ્લેટ",
        "services|6:1|4|q2o1": "મીઠાઈનું બોક્સ",
        "services|6:1|4|q2o2": "નવો દીવો",
        "services|6:1|4|q2o3": "એક કપ કોફી",
        "services|6:1|5|title": "મકાનમાલકણને ફોન",
        "services|6:1|5|scenario": "પુણેમાં રહેતો ભાડૂત રાહુલ ફ્લેટની એક તકલીફ અને ઘર ખાલી કરવા વિશે પોતાનાં મકાનમાલકણ શ્રીમતી જોશીને ફોન કરે છે.",
        "services|6:1|5|l0": "શુભ સાંજ, શ્રીમતી જોશી. હું ફ્લેટ 3બીમાંથી રાહુલ બોલું છું. એક મિનિટ વાત થઈ શકે?",
        "services|6:1|5|l1": "હા, રાહુલ, બોલ. બધું બરાબર છે ને?",
        "services|6:1|5|l2": "પૂરેપૂરું નહીં. સોમવારથી બાથરૂમની છતમાંથી પાણી ટપકે છે, અને દીવાલ ભીની થતી જાય છે.",
        "services|6:1|5|l3": "અરે રે. એ અગાસી પરની ટાંકીને કારણે હશે. હું કાલે સવારે અમારા પ્લમ્બર સુનીલને મોકલીશ.",
        "services|6:1|5|l4": "આભાર. રિપેરનો ખર્ચ મેઇન્ટેનન્સમાંથી જશે, કે મારે ભરવો પડશે?",
        "services|6:1|5|l5": "ચિંતા ન કર, મકાનમાલિક તરીકે એ મારી જવાબદારી છે. તારે ફક્ત બલ્બ જેવી નાની વસ્તુઓનો ખર્ચ આપવાનો.",
        "services|6:1|5|l6": "તમારી મહેરબાની. બીજી એક વાત: મારી કંપની માર્ચમાં મારી બદલી નાશિક કરે છે.",
        "services|6:1|5|l7": "અચ્છા. કરાર પ્રમાણે નોટિસ પિરિયડ બે મહિનાનો છે, એટલે પ્લીઝ જાન્યુઆરી સુધીમાં લેખિત નોટિસ આપી દેજે.",
        "services|6:1|5|l8": "હું આ અઠવાડિયે તમને નોટિસ ઇમેઇલ કરી દઈશ. અને ફ્લેટ ખાલી કરીશ ત્યારે ડિપોઝિટ પાછી મળશે ને?",
        "services|6:1|5|l9": "હા. ફ્લેટ અને છેલ્લું વીજળીનું બિલ તપાસ્યા પછી, હું અઠવાડિયામાં તે ટ્રાન્સફર કરી દઈશ.",
        "services|6:1|5|q0": "રાહુલ કઈ તકલીફની વાત કરે છે?",
        "services|6:1|5|q0o0": "બાથરૂમની છતમાંથી ટપકતું પાણી",
