        "workplace|1:1|0|w5": "સંભાળવું",
        "workplace|1:1|1|p0": "મારી હાલની ભૂમિકામાં હું આખી કંપનીના પગારનું કામ સંભાળું છું.",
        "workplace|1:1|1|p1": "તમે કયા વિભાગમાં કામ કરો છો, અને તમારા ઉપરી કોણ છે?",
        "workplace|1:1|1|p2": "સત્તાવાર રીતે મારો હોદ્દો સિનિયર એનાલિસ્ટનો છે, પણ મારાં કામ દર અઠવાડિયે બદલાય છે.",
        "workplace|1:1|1|p3": "હું છ લોકોની ટીમની દેખરેખ રાખું છું અને ગ્રાહકોના મોટા ભાગના ફોન સંભાળું છું.",
        "workplace|1:1|1|p4": "સામાન્ય દિવસે હું જમ્યા પહેલાં તાકીદનાં કામ પતાવું છું અને બાકીનાનું આયોજન કરું છું.",
        "workplace|1:1|2|w0": "મુખ્ય કાર્યાલય",
