        "workplace|1:1|2|w4": "નિપુણતા",
        "workplace|1:1|2|w5": "વિશેષતા ધરાવવી",
        "workplace|1:1|3|p0": "અમારું મુખ્ય કાર્યાલય બેંગલુરુમાં છે, પણ અમારા મોટા ભાગના કર્મચારીઓ હુબ્બલીમાં છે.",
        "workplace|1:1|3|p1": "અમે એક નાનું સ્ટાર્ટઅપ છીએ, જે દવાખાનાં માટે બિલિંગ સોફ્ટવેર બનાવે છે.",
        "workplace|1:1|3|p2": "મૈસૂર પાસેનો અમારો પ્લાન્ટ ભારતની મોટા ભાગની ટુ-વ્હીલર બ્રાન્ડ માટે બ્રેકના પાર્ટ્સ બનાવે છે.",
        "workplace|1:1|3|p3": "ગ્રામીણ આરોગ્ય સેવામાં અમારી નિપુણતા જ અમને બીજાથી અલગ બનાવે છે.",
        "workplace|1:1|3|p4": "નાનાં શહેરોની દુકાનોને ઓનલાઇન વેચાણ શરૂ કરવામાં મદદ કરવી એ અમારી વિશેષતા છે.",
        "workplace|1:1|4|title": "તમે ખરેખર શું કામ કરો છો?",
        "workplace|1:1|4|text": "ધારવાડમાં એક કૌટુંબિક લગ્નમાં નિખિલના કાકાએ તેને પૂછ્યું કે તે કામ પર ખરેખર શું કરે છે. નિખિલે સમજાવ્યું કે તે ખેડૂતો માટે જમીનના સેન્સર બનાવતા એક સ્ટાર્ટઅપમાં કામ કરે છે. કંપનીનું મુખ્ય કાર્યાલય બેંગલુરુમાં છે, પણ સેન્સરનું ઉત્પાદન હુબ્બલી પાસેની એક નાની ફેક્ટરીમાં થાય છે. તેનો હોદ્દો પ્રોડક્ટ એન્જિનિયરનો છે, અને તે ટેસ્ટિંગ વિભાગમાં છે. તેનું મુખ્ય કામ દરેક નવો સેન્સર ખેડૂતો સુધી જાય તે પહેલાં તેને તપાસવાનું છે. તે બે જુનિયર એન્જિનિયરોની દેખરેખ પણ રાખે છે અને ફેક્ટરીની ટીમના સવાલો સંભાળે છે. કાકાએ હસીને કહ્યું કે કંપનીમાં તો ઘણા બધા કર્મચારીઓ હશે. નિખિલ હસી પડ્યો અને બોલ્યો કે ફક્ત ચાળીસ લોકો છે, પણ દરેક પાસે સાચી નિપુણતા છે.",
        "workplace|1:1|4|q0": "નિખિલની કંપની શું બનાવે છે?",
        "workplace|1:1|4|q0o0": "ખેડૂતો માટે જમીનના સેન્સર",
        "workplace|1:1|4|q0o1": "સ્કૂટરના બ્રેકના પાર્ટ્સ",
        "workplace|1:1|4|q0o2": "દવાખાનાં માટે બિલિંગ સોફ્ટવેર",
        "workplace|1:1|4|q0o3": "લગ્નની કંકોતરીઓ",
        "workplace|1:1|4|q1": "સેન્સરનું ઉત્પાદન ક્યાં થાય છે?",
        "workplace|1:1|4|q1o0": "હુબ્બલી પાસે",
