        "workplace|1:1|4|q2o3": "બે",
        "workplace|1:1|5|title": "તો, તમે શું કરો છો?",
        "workplace|1:1|5|scenario": "બેંગલુરુમાં એક બિઝનેસ કાર્યક્રમમાં અનન્યા અને ફરહાન પહેલી વાર મળે છે અને પોતાની નોકરી વિશે વાત કરે છે.",
        "workplace|1:1|5|l0": "નમસ્તે, હું સહ્યાદ્રિ લોજિસ્ટિક્સમાંથી ફરહાન. તમે આ કાર્યક્રમમાં કેમ આવ્યાં છો?",
        "workplace|1:1|5|l1": "તમને મળીને આનંદ થયો. હું અનન્યા. હું એક ફિનટેક સ્ટાર્ટઅપમાં ગ્રાહક સહાય ટીમની વડી છું.",
        "workplace|1:1|5|l2": "રસપ્રદ. તમારી કંપની બરાબર શું કરે છે?",
        "workplace|1:1|5|l3": "અમે એક એપ બનાવી છે, જે નાના દુકાનદારોને હિસાબ રાખવામાં અને ડિજિટલ પેમેન્ટ લેવામાં મદદ કરે છે.",
        "workplace|1:1|5|l4": "અને તમારો સામાન્ય દિવસ કેવો હોય છે?",
        "workplace|1:1|5|l5": "હું મારી ટીમ સાથે ટૂંકા કોલથી શરૂઆત કરું છું, અને પછી અઘરી ફરિયાદો જાતે સંભાળું છું.",
        "workplace|1:1|5|l6": "એ તો ઘણું મહેનતનું લાગે છે. તમારી ટીમ કેટલી મોટી છે?",
        "workplace|1:1|5|l7": "બે શિફ્ટમાં બાર લોકો. અને તમે? તમારી ભૂમિકા શું છે?",
        "workplace|1:1|5|l8": "હું રૂટ પ્લાનર છું. ટૂંકમાં, હું ધ્યાન રાખું છું કે અમારી ટ્રકો સૌથી ઝડપી અને સસ્તા રસ્તે જાય.",
        "workplace|1:1|5|l9": "તો મારાં પાર્સલ સમયસર આવે છે એ તમારે કારણે છે! સંપર્કમાં રહીએ.",
        "workplace|1:1|5|q0": "અનન્યાની કંપનીએ શું બનાવ્યું છે?",
        "workplace|1:1|5|q0o0": "નાના દુકાનદારો માટે એક એપ",
        "workplace|1:1|5|q0o1": "ટ્રકોનો કાફલો",
        "workplace|1:1|5|q0o2": "હોસ્પિટલો માટે સોફ્ટવેર",
        "workplace|1:1|5|q0o3": "ખેડૂતો માટે સેન્સર",
        "workplace|1:1|5|q1": "અનન્યાની ટીમમાં કેટલા લોકો છે?",
        "workplace|1:1|5|q1o0": "બાર",
        "workplace|1:1|5|q1o1": "છ",
        "workplace|1:1|5|q1o2": "વીસ",
        "workplace|1:1|5|q1o3": "બે",
        "workplace|1:1|5|q2": "ફરહાનની નોકરી શી છે?",
        "workplace|1:1|5|q2o0": "તે ટ્રકો માટે રસ્તાનું આયોજન કરે છે",
        "workplace|1:1|5|q2o1": "તે ટ્રક ચલાવે છે",
        "workplace|1:1|5|q2o2": "તે ફરિયાદો સંભાળે છે",
