        "workplace|4:1|3|p0": "તમારો ઓર્ડર સોમવારે અમારા પુણેના ગોડાઉનમાંથી રવાના કરવામાં આવશે.",
        "workplace|4:1|3|p1": "ઇન્વૉઇસમાં ખોટી રકમ દેખાય છે, એટલે હું એકાઉન્ટ્સ વિભાગને તે સુધારવા કહીશ.",
        "workplace|4:1|3|p2": "હું તમારી અકળામણ સમજું છું, અને આજે જ આ વાત મારા મેનેજર સુધી પહોંચાડીશ.",
        "workplace|4:1|3|p3": "મોડું થયું તેના બદલામાં, આ વખતે અમે ડિલિવરી ચાર્જ માફ કરીશું.",
        "workplace|4:1|3|p4": "હું તમને ખાતરી આપું છું કે બદલામાં મોકલેલી વસ્તુ શુક્રવાર સુધીમાં તમને મળી જશે; એ મારું અંગત વચન છે.",
        "workplace|4:1|4|title": "ક્યારેય ન આવેલાં મેનુ કાર્ડ",
        "workplace|4:1|4|text": "ઇમરાન બેંગલુરુની એક પ્રિન્ટિંગ કંપનીમાં ક્લાયન્ટનાં ખાતાં સંભાળે છે. એક સોમવારે મૈસૂરમાં હોટલ ચલાવતાં શ્રીમતી શેટ્ટીએ ખૂબ નારાજ થઈને તેને ફોન કર્યો. ક્વોટેશનમાં અઠવાડિયામાં ડિલિવરીનું વચન હોવા છતાં તેમનાં નવાં મેનુ કાર્ડ આવ્યાં નહોતાં. ઇમરાને વચ્ચે બોલ્યા વગર સાંભળ્યું અને પછી પોતે બરાબર સમજ્યો છે કે નહીં તે જોવા તેમની જરૂરિયાતો ફરી કહી સંભળાવી. તેને ખબર પડી કે ઇન્વૉઇસમાં ભૂલને કારણે ઓર્ડર ક્યારેય રવાના જ થયો નહોતો. તેણે આ તકલીફ પોતાના મેનેજર સુધી પહોંચાડી અને તે જ બપોરે કુરિયરની વ્યવસ્થા કરી. મોડું થયું તેના બદલામાં કંપનીએ શ્રીમતી શેટ્ટીના બિલમાંથી દસ ટકા ઓછા કર્યા. ઇમરાને તેમને ખાતરી આપી કે ભવિષ્યના તેમના ઓર્ડર તે જાતે તપાસશે, અને તેઓ કંપની સાથે જ રહ્યાં.",
        "workplace|4:1|4|q0": "શ્રીમતી શેટ્ટી કેમ નારાજ હતાં?",
        "workplace|4:1|4|q0o0": "તેમનાં મેનુ કાર્ડ આવ્યાં નહોતાં",
        "workplace|4:1|4|q0o1": "કાર્ડમાં જોડણીની ભૂલો હતી",
        "workplace|4:1|4|q0o2": "ભાવ બહુ વધારે હતો",
        "workplace|4:1|4|q0o3": "ઇમરાને તેમનો ફોન ન ઉપાડ્યો",
        "workplace|4:1|4|q1": "ઓર્ડર રવાના કેમ નહોતો થયો?",
        "workplace|4:1|4|q1o0": "ઇન્વૉઇસમાં ભૂલ હતી",
        "workplace|4:1|4|q1o1": "પ્રિન્ટિંગ મશીન બગડેલું હતું",
        "workplace|4:1|4|q1o2": "કુરિયરવાળો રજા પર હતો",
        "workplace|4:1|4|q1o3": "શ્રીમતી શેટ્ટીએ પૈસા નહોતા ચૂકવ્યા",
        "workplace|4:1|4|q2": "મોડું થયું તેના બદલામાં કંપનીએ શું કર્યું?",
        "workplace|4:1|4|q2o0": "બિલમાંથી દસ ટકા ઓછા કર્યા",
        "workplace|4:1|4|q2o1": "મફત વિઝિટિંગ કાર્ડ છાપી આપ્યાં",
        "workplace|4:1|4|q2o2": "નવું પ્રિન્ટર મોકલ્યું",
        "workplace|4:1|4|q2o3": "બધા પૈસા પાછા આપ્યા",
        "workplace|4:1|5|title": "નવો ક્લાયન્ટ",
        "workplace|4:1|5|scenario": "હુબ્બલીની એક ફર્નિચર કંપનીનાં સેલ્સ મેનેજર નેહા વિક્રમ કુલકર્ણીનો ફોન ઉપાડે છે, જેમને નવી ઓફિસ માટે ફર્નિચર જોઈએ છે.",
        "workplace|4:1|5|l0": "નમસ્તે, શ્રી કુલકર્ણી. સંપર્ક કરવા બદલ આભાર. અમે શું મદદ કરી શકીએ?",
        "workplace|4:1|5|l1": "અમે બેલગાવીમાં નવી ઓફિસ ખોલીએ છીએ અને ચાળીસ લોકો માટે ટેબલ અને ખુરશીઓ જોઈએ છે.",
        "workplace|4:1|5|l2": "સરસ. તમારી જરૂરિયાતો વિશે થોડું વધુ કહેશો? તમારા મનમાં કોઈ બજેટ કે ડિઝાઇન છે?",
        "workplace|4:1|5|l3": "કંઈક સાદું અને આરામદાયક. અમારું બજેટ આશરે આઠ લાખ રૂપિયા છે.",
        "workplace|4:1|5|l4": "એટલામાં સારી રીતે થઈ જશે. તમારે બધું ક્યાં સુધીમાં જોઈએ?",
        "workplace|4:1|5|l5": "આવતા મહિનાની પંદરમી સુધીમાં. એ તારીખ અમારા માટે ખૂબ મહત્ત્વની છે.",
        "workplace|4:1|5|l6": "સમજી ગઈ. શુક્રવાર સુધીમાં હું તમને બે વિકલ્પવાળો પ્રસ્તાવ અને ક્વોટેશન મોકલીશ.",
        "workplace|4:1|5|l7": "શું તમારી ટીમ સાઇટ પર ફિટિંગનું કામ પણ સંભાળી શકશે?",
        "workplace|4:1|5|l8": "હા, ફિટિંગ સામેલ છે. અને હું તમને ખાતરી આપું છું કે અમે તમારી સમયમર્યાદા સાચવીશું.",
        "workplace|4:1|5|l9": "સરસ. તો હું તમારા પ્રસ્તાવની રાહ જોઈશ.",
        "workplace|4:1|5|q0": "ફર્નિચર કેટલા લોકો માટે છે?",
