        "workplace|5:1|0|w4": "ગેરહાજર",
        "workplace|5:1|0|w5": "ઘરેથી કામ કરવું",
        "workplace|5:1|1|p0": "મને સખત તાવ છે, એટલે આજે મારે માંદગીની રજા લેવી છે.",
        "workplace|5:1|1|p1": "મારા ભાઈના કોલેજ પ્રવેશ માટે શુક્રવારે હું અડધા દિવસની રજા લઈ શકું?",
        "workplace|5:1|1|p2": "ટ્રેનની ટિકિટ બુક કરતાં પહેલાં હું મારી બાકી રજા જોઈ લઉં.",
        "workplace|5:1|1|p3": "મારા મેનેજરે દસમીથી ચૌદમી સુધીની મારી રજા મંજૂર કરી છે.",
        "workplace|5:1|1|p4": "સોમવારે હું ગેરહાજર હતો તે બદલ માફ કરજો; બાકી કામ પૂરું કરવા કાલે હું ઘરેથી કામ કરી શકું?",
        "workplace|5:1|2|w0": "અદલાબદલી કરવી",
        "workplace|5:1|2|w1": "બદલે કામ સંભાળવું",
        "workplace|5:1|2|w2": "કામની સોંપણી",
        "workplace|5:1|2|w3": "સમય બદલવો",
        "workplace|5:1|2|w4": "લવચીક",
        "workplace|5:1|2|w5": "અગાઉથી",
        "workplace|5:1|3|p0": "આવતા શનિવારે તમે મારી સાથે શિફ્ટની અદલાબદલી કરશો?",
        "workplace|5:1|3|p1": "હું ન હોઉં ત્યારે મારા કોલ સંભાળવા પ્રિયા તૈયાર થઈ છે.",
        "workplace|5:1|3|p2": "ગુરુવારે હું બરાબર રીતે કામ સોંપી દઈશ, જેથી કંઈ રહી ન જાય.",
        "workplace|5:1|3|p3": "આપણી રિવ્યૂ મીટિંગ આવતા અઠવાડિયે રાખી શકીએ? સોમવારે હું રજા પર છું.",
        "workplace|5:1|3|p4": "આપણા મેનેજર લવચીક છે, બસ આપણે ઓછામાં ઓછું એક અઠવાડિયું અગાઉથી પૂછવું જોઈએ.",
        "workplace|5:1|4|title": "ઉડુપીમાં લગ્ન",
        "workplace|5:1|4|text": "સૌમ્યા બેંગલુરુમાં એક બેંકની મુખ્ય ઓફિસની પેમેન્ટ્સ ટીમમાં કામ કરે છે. તેના પિતરાઈનાં લગ્ન ઉડુપીમાં માર્ચના છેલ્લા અઠવાડિયામાં હતાં, જે વર્ષનો સૌથી વ્યસ્ત સમય હોય છે. તેણે પોતાની બાકી રજા જોઈ તો હજી નવ દિવસ બાકી હતા. ત્રણ અઠવાડિયાં અગાઉથી તેણે પોતાના મેનેજર શ્રી ભટ પાસે ચાર દિવસની રજા માંગી અને નમ્રતાથી કારણ સમજાવ્યું. તેણે લગ્ન પછીના દિવસે ઘરેથી કામ કરવાની તૈયારી પણ બતાવી. શ્રી ભટ લવચીક હતા, પણ તેમણે પૂછ્યું કે મહિનાના અંતના રિપોર્ટ કોણ સંભાળશે. સૌમ્યાએ પોતાના સાથી રાકેશ સાથે બે શિફ્ટની અદલાબદલી કરી અને જતાં પહેલાં બધું કામ બરાબર સોંપવાનું વચન આપ્યું. તેની યોજનાથી ખુશ થઈને શ્રી ભટે તે જ બપોરે રજા મંજૂર કરી.",
