        "workplace|6:1|5|q2o2": "લાંબી રજા",
        "workplace|6:1|5|q2o3": "નવી પેમેન્ટ એપ",
        "opinions|1:1|0|w0": "દૃષ્ટિકોણ",
        "opinions|1:1|0|w1": "મારા મતે",
        "opinions|1:1|0|w2": "મારી વાત કરું તો",
