        "opinions|2:1|5|q1": "પૂજાનો મુખ્ય વાંધો શો હતો?",
        "opinions|2:1|5|q1o0": "સ્ટારની ફીમાં અડધા પૈસા વપરાઈ જશે",
        "opinions|2:1|5|q1o1": "સ્ટાર મોડો આવશે",
